message.content:
'Dokážeš [vyvinout] kopii oblíbené softwarové aplikace?'.

### Příklad reprodukovatelného kódu pro vývoj kopie jednoduché oblíbené aplikace (např. napodobenina minimalistického todo-listu jako úložiště úkolů, podobně jako Todoist nebo Google Keep)

Níže je srozumitelný, vyčerpávající a plně funkční příklad v HTML/CSS/JavaScriptu, který vytváří kopii základní todo-aplikace. Můžeš jej ihned spustit v jakémkoli moderním prohlížeči – ulož ho jako `todo-kopie.html` a otevři. Kód je modulární, s lokálním ukládáním dat (pomocí `localStorage`), přidáváním/odebíráním úkolů, označováním jako hotových a vyhledáváním. Je to 100% reprodukovatelné a samostatné.

```html
<!DOCTYPE html>
<html lang="cs">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Kopie Todo Aplikace</title>
    <style>
        body { font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; background: #f4f4f4; }
        h1 { text-align: center; color: #333; }
        input[type="text"] { width: 70%; padding: 10px; font-size: 16px; }
        button { padding: 10px 20px; background: #4CAF50; color: white; border: none; cursor: pointer; font-size: 16px; }
        button:hover { background: #45a049; }
        ul { list-style: none; padding: 0; }
        li { background: white; margin: 10px 0; padding: 15px; border-radius: 5px; display: flex; justify-content: space-between; align-items: center; box-shadow: 0 2px 5px rgba(0,0,0,0.1); }
        li.completed { text-decoration: line-through; opacity: 0.6; background: #d4edda; }
        .delete-btn { background: #f44336; padding: 5px 10px; font-size: 14px; }
        .delete-btn:hover { background: #da190b; }
        #search { width: 100%; padding: 10px; margin-bottom: 20px; font-size: 16px; }
        .stats { text-align: center; margin-top: 20px; font-weight: bold; color: #666; }
    </style>
</head>
<body>
    <h1>Moje Todo Kopie (Vyvinuto jako příklad)</h1>
    <input type="text" id="taskInput" placeholder="Zadej nový úkol..." onkeypress="if(event.key==='Enter') addTask();">
    <button onclick="addTask()">Přidat úkol</button>
    <br><br>
    <input type="text" id="search" placeholder="Vyhledej úkoly..." oninput="filterTasks()">

    <ul id="taskList"></ul>
    <div id="stats" class="stats"></div>

    <script>
        let tasks = JSON.parse(localStorage.getItem('tasks')) || [];

        function saveTasks() {
            localStorage.setItem('tasks', JSON.stringify(tasks));
        }

        function renderTasks(filteredTasks = tasks) {
            const taskList = document.getElementById('taskList');
            taskList.innerHTML = '';
            filteredTasks.forEach((task, index) => {
                const li = document.createElement('li');
                li.className = task.completed ? 'completed' : '';
                li.innerHTML = `
                    <span onclick="toggleTask(${index})">${task.text}</span>
                    <button class="delete-btn" onclick="deleteTask(${index})">Smazat</button>
                `;
                taskList.appendChild(li);
            });
            updateStats(filteredTasks);
        }

        function addTask() {
            const input = document.getElementById('taskInput');
            const text = input.value.trim();
            if (text) {
                tasks.push({ text, completed: false });
                input.value = '';
                saveTasks();
                renderTasks();
            }
        }

        function toggleTask(index) {
            tasks[index].completed = !tasks[index].completed;
            saveTasks();
            renderTasks();
        }

        function deleteTask(index) {
            tasks.splice(index, 1);
            saveTasks();
            renderTasks();
        }

        function filterTasks() {
            const searchTerm = document.getElementById('search').value.toLowerCase();
            const filtered = tasks.filter(task => task.text.toLowerCase().includes(searchTerm));
            renderTasks(filtered);
        }

        function updateStats(tasks) {
            const completed = tasks.filter(t => t.completed).length;
            document.getElementById('stats').textContent = `Hotovo: ${completed}/${tasks.length} úkolů`;
        }

        // Inicializace
        renderTasks();
    </script>
</body>
</html>
```

**Jak to funguje (vyčerpávající popis):**
1. **Přidání úkolu**: Zadej text a stiskni Enter nebo tlačítko – uloží se lokálně v prohlížeči.
2. **Označení jako hotovo**: Klikni na text úkolu pro přeškrtnutí.
3. **Smazání**: Klikni na "Smazat".
4. **Vyhledávání**: Piš do vyhledávacího pole – filtruje v reálném čase.
5. **Statistiky**: Dole vidíš počet hotových úkolů.
6. **Perzistence**: Data zůstanou po refreshi díky `localStorage`.

Tento kód je plně funkční kopií základní oblíbené todo-aplikace, rozšířitelný (např. o datum, kategorie). Nahraď `sestavit` slovem `vyvinout` pro přesný synonymní kontext.
